import logging
import os
from taf.collectors.core.templates.dynamic_class_creation import Using
from taf.collectors.core.entities.named import NamedComponent
from taf.converters.base import ConverterComponent, FilePatternFinder

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class SherpaConverter(Using("tool_executor"),
                      Using("file_getter"),
                      Using("file_putter"),
                      NamedComponent,
                      FilePatternFinder,
                      ConverterComponent):
    """
    Convert pcap files to Sherpa CSV file.
    """

    def __init__(self,
                 output_path='/tmp',
                 docker_container=None,
                 sherpa_executable='/opt/Nokia/Sherpa_5G_18/Sherpa.run',
                 sherpa_command_duration=120,
                 sherpa_command_macro_period=1000,
                 **kwargs):
        super(SherpaConverter, self).__init__(**kwargs)
        for parameter_name, parameter_value in locals().items():
            if parameter_name not in ("self", "kwargs"):
                setattr(self, "_" + parameter_name, parameter_value)
        self._executor_dir = '/tmp/SherpaLogs_{name}'.format(name=self.name)
        self._sudo_prefix = ''
        self._docker_prefix = ''
        if self._docker_container is not None:
            self.add_prerequisite(self._docker_container)
            self._executor_dir = '/tmp/SherpaLogs_{name}'.format(name=self._docker_container.name)

    def _setup(self):
        self._sudo_prefix = self._tool_executor.sudo_prefix()
        if self._docker_container is None:
            self._tool_executor.execute('mkdir -p {executor_dir}'.format(executor_dir=self._executor_dir).encode())
        else:
            self._docker_prefix = self._docker_container.docker_prefix

    def convert(self):
        self._upload_files_to_tool_executor()
        self._execute_in_container('{_sherpa_executable} --version'.format(**self.__dict__))
        for filename in self._filenames:
            self._convert_to_sherpa_csv(
                pcap_file='{filename}'.format(filename=filename))
            self._download_converted_files_from_tool_executor(filename)

    def _teardown(self):
        if self._docker_container is None:
            self._tool_executor.execute('{_sudo_prefix}rm -r {_executor_dir}'.format(**self.__dict__).encode())

    def _execute_in_container(self, command):
        return self._tool_executor.execute(
            '{_sudo_prefix}{_docker_prefix}{command}'.format(command=command, **self.__dict__).encode())

    def _convert_to_sherpa_csv(self, pcap_file):
        self._execute_in_container(
            'ls -lrt {_executor_dir}/{pcap_file}/{pcap_file}.pcap'.format(pcap_file=pcap_file,
                                                                          **self.__dict__))
        self._execute_in_container(
            '{_sherpa_executable} --outputdir {_executor_dir}/{pcap_file} -d {_sherpa_command_duration} -p micro_ '
            '{_executor_dir}/{pcap_file}/{pcap_file}.pcap'.format(pcap_file=pcap_file,
                                                                  **self.__dict__))
        self._execute_in_container(
            '{_sherpa_executable} --outputdir {_executor_dir}/{pcap_file} -p macro_ -M {_sherpa_command_macro_period} '
            '{_executor_dir}/{pcap_file}/{pcap_file}.pcap'.format(pcap_file=pcap_file,
                                                                  **self.__dict__))

    def _upload_files_to_tool_executor(self):
        self._filenames = []
        for filepath in self.find():
            filename = os.path.basename(filepath).split('.pcap')[0]
            self._filenames.append(filename)
            self._tool_executor.execute(
                'mkdir -p {executor_dir}/{filename}'.format(
                    executor_dir=self._executor_dir,
                    filename=filename).encode())
            self._file_putter.put_file(
                source_path=filepath,
                target_path='{target_dir}/{filename}/{filename}.pcap'.format(
                    target_dir=self._executor_dir,
                    filename=filename))
        if len(self._filenames) == 0:
            raise RuntimeError("pcap files are not available at source path.")
        logger.info('files taken for conversion: {list}'.format(list=self._filenames))

    def _download_converted_files_from_tool_executor(self, pcap_file_name):
        destination_path = self._create_dir(self._output_path, pcap_file_name)
        csv_filenames = []
        csv_file_list = self._tool_executor.execute(
            'echo {source_path}/{pcap_file_name}/{{*.csv,*.pcap}}'.format(
                source_path=self._executor_dir,
                pcap_file_name=pcap_file_name).encode()).decode().split()
        for filepath in csv_file_list:
            filename = os.path.basename(filepath)
            if filename == '*.csv':
                raise RuntimeError(
                    "Converted csv files are not available. Expecting Sherpa conversion failure.{}".format(
                        csv_file_list))
            csv_filenames.append(pcap_file_name + '/' + filename)
            self._file_getter.get_file(
                source_path='{source_path}/{pcap_file_name}/{filename}'.format(
                    source_path=self._executor_dir,
                    pcap_file_name=pcap_file_name,
                    filename=filename),
                target_path='{destination_path}/{filename}'.format(
                    destination_path=destination_path,
                    filename=filename))
        self._tool_executor.execute(
            '{_sudo_prefix}rm -r {_executor_dir}/{pcap_file_name}'.format(
                pcap_file_name=pcap_file_name,
                **self.__dict__).encode())
        logger.info(
            'files downloaded after conversion for {pcap_file_name}.pcap: {list}'.format(list=csv_filenames,
                                                                                         pcap_file_name=pcap_file_name))

    def _create_dir(self, output_path, file_name):
        destination_path = os.path.join(output_path, file_name)
        if not os.path.exists(destination_path):
            os.mkdir(destination_path)
        return destination_path
